        private static void Register(string ns, string name, int typeDef, int methods, Func<IProtocolMessage> factory)
        {
            var desc = new ProtocolDescriptor
            {
                Namespace = ns,
                ClassName = name,
                TypeDefIndex = typeDef,
                MethodCount = methods,
                Factory = factory
            };
            _messages[name] = desc;
            _messages[$"{ns}.{name}"] = desc;
        }

        public static bool TryGetDescriptor(string name, out ProtocolDescriptor desc) => _messages.TryGetValue(name, out desc);
        public static IProtocolMessage CreateMessage(string name)
        {
            if (!_initialized) Initialize();
            return _messages.TryGetValue(name, out var d) ? d.Factory() : new GenericProtocolMessage(name, 0);
        }
